def histogram(test):
    result = {}
    max_count = 0
    letter = ""
    candidate = ""
    count = 0
    phase = 1

    for letter in test:
        if letter != " ":
            count = 0
            for candidate in test:
                if candidate == letter:
                    count = count + 1
            if count > max_count:
                max_count = count

    phase = 2
    for letter in test:
        if letter != " ":
            count = 0
            for candidate in test:
                if candidate == letter:
                    count = count + 1
            if count != max_count:
                result[letter] = count

    return result


assert histogram("b b b b a") == {"b": 4}

/workspace/differential_test.py.content:
from collections import Counter
from itertools import product

from solution import histogram


def oracle(text):
    counts = Counter(character for character in text if character != " ")
    if not counts:
        return {}
    maximum = max(counts.values())
    return {
        character: count
        for character, count in counts.items()
        if count == maximum
    }


alphabet = "abc "
cases = [
    "".join(characters)
    for length in range(8)
    for characters in product(alphabet, repeat=length)
]
cases.extend([
    "a b c",
    "a b b a",
    "a b c a b",
    "b b b b a",
    "",
])

mismatches = []
for case in cases:
    actual = histogram(case)
    expected = oracle(case)
    if actual != expected:
        mismatches.append((case, actual, expected))

print("cases:", len(cases))
print("mismatches:", len(mismatches))
if mismatches:
    print("first mismatch:", mismatches[0])
    raise SystemExit(1)

